// Gesture surface index — record JAH-GPCS-TOUCHPAD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"size_in2": 30, "gesture_count": 12, "price_usd": 130};
var value = (m.size_in2*m.gesture_count/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-TOUCHPAD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-TOUCHPAD-000001|' + value.toFixed(2) + ' surface index');

